#[cfg(test)]
mod tests {
    use super::USAGE;
    #[test]
    fn original_resource_order_required_markers_and_skipped_directives() {
        let resources: Vec<_> = USAGE.split(" |\n").collect();
        assert_eq!(resources.len(), 14);
        assert!(resources[0].starts_with("add client "));
        assert_eq!(resources[0].matches("=<").count(), 39);
        assert!(resources[1].starts_with("add jobdefs "));
        assert_eq!(resources[1].matches("=<").count(), 81);
        assert!(resources[2].starts_with("add job "));
        assert_eq!(resources[2].matches("=<").count(), 81);
        assert!(resources[3].starts_with("add storage "));
        assert_eq!(resources[3].matches("=<").count(), 35);
        assert!(resources[4].starts_with("add catalog "));
        assert_eq!(resources[4].matches("=<").count(), 15);
        assert!(resources[5].starts_with("add schedule "));
        assert_eq!(resources[5].matches("=<").count(), 4);
        assert!(resources[6].starts_with("add fileset "));
        assert_eq!(resources[6].matches("=<").count(), 4);
        assert!(resources[7].starts_with("add pool "));
        assert_eq!(resources[7].matches("=<").count(), 29);
        assert!(resources[8].starts_with("add messages "));
        assert_eq!(resources[8].matches("=<").count(), 17);
        assert!(resources[9].starts_with("add counter "));
        assert_eq!(resources[9].matches("=<").count(), 6);
        assert!(resources[10].starts_with("add profile "));
        assert_eq!(resources[10].matches("=<").count(), 12);
        assert!(resources[11].starts_with("add console "));
        assert_eq!(resources[11].matches("=<").count(), 29);
        assert!(resources[12].starts_with("add user "));
        assert_eq!(resources[12].matches("=<").count(), 13);
        assert_eq!(*resources.last().unwrap(), "export client=<client>");
        let client = resources[0];
        assert!(client.contains(" name=<NAME>"));
        assert!(client.contains(" address=<STRING>"));
        assert!(client.contains(" password=<AUTOPASSWORD>"));
        assert!(client.contains(" [tlsenable=<BOOLEAN>]"));
        assert!(!client.contains("fileretention="));
        assert!(!client.contains("fdaddress="));
        assert!(!USAGE.contains("runscript="));
        assert!(!USAGE.contains("include="));
        assert!(!USAGE.contains("add director "));
        assert!(!USAGE.contains("add device "));
    }
}
